                <Button mt="4" onClick={() => setFilters(DEFAULT_FILTERS)}>
                  Clear filters
                </Button>
              </Box>
            ) : (
              <Grid
                as="ul"
                listStyleType="none"
                m="0"
                p="0"
                templateColumns={{
                  base: "1fr",
                  md: "repeat(2, minmax(0, 1fr))",
