                  "2xl": "repeat(2, minmax(0, 1fr))",
                }}
                gap="4"
              >
                {results.map((home) => (
                  <li key={home.id}>
                    <HomeCard
                      home={home}
                      highlighted={
                        hoveredId === home.id || selectedId === home.id
                      }
                      saved={saved.includes(home.id)}
                      onToggleSave={toggleSave}
                      onHover={setHoveredId}
                    />
                  </li>
                ))}
              </Grid>
            )}
          </Box>

          <Box
            display={{
              base: view === "map" ? "block" : "none",
              lg: "block",
            }}
            position={{ lg: "sticky" }}
            top={{ lg: "190px" }}
            height={{ base: "calc(100dvh - 330px)", lg: "calc(100dvh - 220px)" }}
            minH="360px"
            rounded="lg"
            overflow="hidden"
            borderWidth="1px"
          >
            <LazyHomeMap
              homes={results}
              hoveredId={hoveredId}
              selectedId={selectedId}
              onHover={setHoveredId}
              onSelect={handleSelect}
              visible={view === "map" || true}
              label={`Map of ${results.length} homes in ${CITY}`}
            />
          </Box>
        </Grid>
      </Container>
    </Flex>
  );
}
