import { Box, HStack, Text } from "@chakra-ui/react";

const SCALE = ["A+", "A", "B", "C", "D", "E", "F"];
const COLORS: Record<string, string> = {
  "A+": "#0b7a3b",
  A: "#2f9e44",
  B: "#74b816",
  C: "#c0b60f",
  D: "#f59f00",
