          const active = s === rating;
          return (
            <Box
              key={s}
              aria-hidden="true"
              display="flex"
              alignItems="center"
              justifyContent="center"
              width={active ? "48px" : "34px"}
              height={active ? "48px" : "34px"}
              rounded="md"
              color="white"
              fontWeight="bold"
              fontSize={active ? "lg" : "sm"}
              style={{
                background: COLORS[s],
                opacity: active ? 1 : 0.35,
                outline: active ? "3px solid currentColor" : "none",
              }}
            >
              {s}
            </Box>
          );
        })}
      </HStack>
      <Text fontSize="sm" color="fg.muted" mt="2">
