}

export default async function HomePage({ params }: { params: Params }) {
  const { id } = await params;
  const home = getHome(id);
  if (!home) notFound();

  const facts = [
    { icon: LuBedDouble, label: "Bedrooms", value: home.beds === 0 ? "Studio" : String(home.beds) },
    { icon: LuBath, label: "Bathrooms", value: String(home.baths) },
    { icon: LuRuler, label: "Area", value: `${home.area_m2} m²` },
    { icon: LuCalendar, label: "Built", value: String(home.year) },
  ];

  return (
    <Box bg="bg.subtle" minH="100dvh">
      <Box as="header" bg="bg.panel" borderBottomWidth="1px">
        <Container maxW="6xl" py="3">
          <HStack justify="space-between">
            <Text fontWeight="bold" fontSize="xl" color="teal.600">
              Haven
            </Text>
            <NextLink
              href="/"
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 6,
                fontWeight: 500,
              }}
            >
              <LuArrowLeft aria-hidden="true" /> Back to search
            </NextLink>
          </HStack>
        </Container>
      </Box>

      <Container as="main" maxW="6xl" py={{ base: "4", md: "6" }}>
        <GalleryStrip id={home.id} title={home.title} />

        <Grid
          mt="6"
          gap="6"
          templateColumns={{ base: "1fr", lg: "minmax(0, 3fr) minmax(0, 2fr)" }}
          alignItems="start"
        >
          <Flex direction="column" gap="6" minW="0">
            <Box>
              <HStack gap="2" wrap="wrap">
                <Badge colorPalette="teal">{home.type}</Badge>
                {isNewListing(home) && (
                  <Badge colorPalette="green" variant="solid">
                    New
                  </Badge>
                )}
              </HStack>
              <Heading as="h1" size="3xl" mt="2">
                {home.title}
              </Heading>
              <Text color="fg.muted" mt="1">
                {home.district}, {CITY} · Listed {formatDate(home.listed)}
              </Text>
              <Text fontSize="3xl" fontWeight="bold" mt="3">
                {formatPrice(home.price)}
              </Text>
              <Text color="fg.muted" fontSize="sm">
                {formatPrice(Math.round(home.price / home.area_m2))} per m²
              </Text>
            </Box>

            <Box
              as="section"
              aria-label="Key facts"
              bg="bg.panel"
              borderWidth="1px"
              rounded="lg"
              p="4"
            >
              <Grid
                as="dl"
                templateColumns={{ base: "repeat(2, 1fr)", md: "repeat(4, 1fr)" }}
                gap="4"
                m="0"
              >
                {facts.map((f) => (
                  <Box key={f.label}>
                    <Box as="dt" color="fg.muted" fontSize="sm">
                      <HStack gap="1.5">
                        <f.icon aria-hidden="true" />
                        <span>{f.label}</span>
                      </HStack>
                    </Box>
                    <Box as="dd" m="0" fontSize="xl" fontWeight="semibold">
                      {f.value}
                    </Box>
                  </Box>
                ))}
              </Grid>
            </Box>

            <Box as="section" aria-labelledby="features-heading">
              <Heading as="h2" size="lg" id="features-heading">
                Features
              </Heading>
              <List.Root as="ul" mt="3" gap="2" variant="plain">
                {home.features.map((feature) => (
                  <List.Item key={feature}>
                    <List.Indicator asChild color="teal.600">
                      <LuCheck aria-hidden="true" />
                    </List.Indicator>
                    {feature}
                  </List.Item>
                ))}
              </List.Root>
            </Box>

            <Box as="section" aria-labelledby="energy-heading">
              <Heading as="h2" size="lg" id="energy-heading" mb="3">
                Energy rating
              </Heading>
              <EnergyRating rating={home.energy} />
            </Box>

            <Box as="section" aria-labelledby="location-heading">
              <Heading as="h2" size="lg" id="location-heading" mb="3">
                Location
              </Heading>
              <DetailMap home={home} />
            </Box>
          </Flex>

          <Box position={{ lg: "sticky" }} top={{ lg: "4" }}>
            <ContactForm homeTitle={home.title} />
          </Box>
        </Grid>
      </Container>
    </Box>
  );
}
```

I'm using the `List` component with `variant="plain"` and `List.Indicator asChild`. I'll verify these exist in the docs before finalizing.

Chakra components work in server components, but compound components like `List.Root` and passing the icon component `f.icon` can be fragile, so I'll replace `List` with a plain `ul` and render facts without a component-as-prop pattern. I'll also drop `as="header"`-style risks by keeping those as plain `Box as=...` elements, which are fine.

