                {formatPrice(home.price)}
              </Text>
              <Text color="fg.muted" fontSize="sm">
                {formatPrice(Math.round(home.price / home.area_m2))} per m²
              </Text>
            </Box>

            <Box
              as="section"
              aria-label="Key facts"
